export function initEventsAnimations() {
  const eventsEl = document.querySelector(".section-6") || document.querySelector("#evenements")?.closest("section") || document.querySelector(".section-events");
  if (!eventsEl) return;

  const slots = Array.from(eventsEl.querySelectorAll(".gallery-slot"));
  const contents = eventsEl.querySelectorAll(".event-content");
  if (!slots.length || !contents.length) return;

  const duration = 6;
  let timerTween = null;
  let isTransitioning = false;

  // SplitText setup helper
  function setupSplit(el) {
    const title = el.querySelector(".event-title");
    if (title && !el._splitText && window.SplitText) {
      const split = new window.SplitText(title, { type: "lines", linesClass: "line-inner" });
      split.lines.forEach((line) => {
        const mask = document.createElement("div");
        mask.className = "line-mask";
        mask.style.overflow = "hidden";
        line.parentNode.insertBefore(mask, line);
        mask.appendChild(line);
      });
      el._splitText = split;
    }
    const split = el._splitText;
    const desc = el.querySelector(".event-description, .text-block-6");
    const badges = el.querySelectorAll(".badge-square, .badge-round");
    const btn = el.querySelector(".event-button, .btn-bubble-arrow");

    if (split?.lines?.length) window.gsap.set(split.lines, { yPercent: 110, rotation: 5, opacity: 0 });
    if (desc) window.gsap.set(desc, { y: 30, opacity: 0 });
    if (badges.length) window.gsap.set(badges, { yPercent: 120, rotation: 10, opacity: 0 });
    if (btn) window.gsap.set(btn, { y: 30, opacity: 0 });
  }

  function animateIn(el) {
    const split = el._splitText;
    const desc = el.querySelector(".event-description, .text-block-6");
    const badges = el.querySelectorAll(".badge-square, .badge-round");
    const btn = el.querySelector(".event-button, .btn-bubble-arrow");
    const tl = window.gsap.timeline();

    if (badges.length) {
      tl.to(badges, { yPercent: 0, rotation: 0, opacity: 1, duration: 1.2, stagger: 0.1, ease: "power4.out", force3D: true }, 0);
    }
    if (split?.lines?.length) {
      tl.to(split.lines, { yPercent: 0, rotation: 0, opacity: 1, duration: 1.4, stagger: 0.1, ease: "power4.out", force3D: true }, 0.1);
    }
    if (desc) {
      tl.to(desc, { y: 0, opacity: 1, duration: 0.8, ease: "power3.out" }, 0.4);
    }
    if (btn) {
      tl.to(btn, { y: 0, opacity: 1, duration: 0.8, ease: "power3.out" }, 0.6);
    }
    return tl;
  }

  function animateOut(el) {
    const split = el._splitText;
    const desc = el.querySelector(".event-description, .text-block-6");
    const badges = el.querySelectorAll(".badge-square, .badge-round");
    const btn = el.querySelector(".event-button, .btn-bubble-arrow");
    const tl = window.gsap.timeline();

    if (split?.lines?.length) {
      tl.to(split.lines, { yPercent: -110, rotation: -2, opacity: 0, duration: 0.6, ease: "power3.in" }, 0);
    }
    const elements = [];
    if (desc) elements.push(desc);
    if (badges.length) elements.push(badges);
    if (btn) elements.push(btn);
    if (elements.length) {
      tl.to(elements, { y: -20, opacity: 0, duration: 0.5, ease: "power3.in" }, 0.1);
    }

    tl.eventCallback("onComplete", () => {
      if (split) {
        split.revert();
        delete el._splitText;
      }
    });
    return tl;
  }

  function startProgress(index) {
    if (timerTween) timerTween.kill();
    eventsEl.querySelectorAll(".slot-progress-fill").forEach((fill) => {
      window.gsap.set(fill, { width: "0%" });
    });

    const activeSlot = slots[index];
    if (!activeSlot) return;

    const fillBar = activeSlot.querySelector(".slot-progress-fill");
    if (!fillBar) return;

    timerTween = window.gsap.to(fillBar, {
      width: "100%",
      duration: duration,
      ease: "none",
      onComplete: () => {
        const nextIndex = (index + 1) % slots.length;
        if (!isTransitioning) slots[nextIndex].click();
      }
    });
  }

  // Create progress bar containers in each slot if not already present
  slots.forEach((slot) => {
    if (!slot.querySelector(".slot-progress-container")) {
      const container = document.createElement("div");
      container.className = "slot-progress-container";
      const fill = document.createElement("div");
      fill.className = "slot-progress-fill";
      container.appendChild(fill);
      slot.appendChild(container);
    }
  });

  // Slot click handling
  slots.forEach((slot, index) => {
    slot.addEventListener("click", () => {
      if (isTransitioning || slot.classList.contains("is-active")) return;
      const targetId = slot.dataset.target;
      const targetContent = eventsEl.querySelector(`#${targetId}`);
      const activeContent = eventsEl.querySelector(".event-content.is-active");

      if (targetContent && activeContent) {
        isTransitioning = true;
        if (timerTween) timerTween.pause();

        slots.forEach((s) => s.classList.remove("is-active"));
        slot.classList.add("is-active");

        animateOut(activeContent).eventCallback("onComplete", () => {
          activeContent.classList.remove("is-active");
          targetContent.classList.add("is-active");
          setupSplit(targetContent);
          const inTl = animateIn(targetContent);
          isTransitioning = false;
          inTl.eventCallback("onComplete", () => startProgress(index));
        });
      }
    });
  });

  // ScrollTrigger to start when scrolled into view
  const activeContent = eventsEl.querySelector(".event-content.is-active");
  const activeIndex = slots.findIndex((s) => s.classList.contains("is-active"));
  const startIndex = activeIndex > -1 ? activeIndex : 0;

  if (activeContent) setupSplit(activeContent);

  if (window.ScrollTrigger) {
    window.ScrollTrigger.create({
      trigger: eventsEl.querySelector(".event-pin-height") || eventsEl,
      start: "top 85%",
      once: true,
      onEnter: () => {
        if (activeContent) {
          animateIn(activeContent).eventCallback("onComplete", () => startProgress(startIndex));
        } else {
          startProgress(startIndex);
        }
      }
    });
  } else {
    startProgress(startIndex);
  }
}
